        $metadata->addPropertyConstraint('firstName', new Assert\NotBlank());
        $metadata->addPropertyConstraint('firstName', new Assert\Length(min: 4));
        $metadata->addPropertyConstraint('lastName', new Assert\NotBlank());
    }
}

